#!/usr/bin/env bash
# Generated by CANN_OpHelper verifygen -- one-key build + run + numeric compare.
# Run from the cloud CANN environment at the project root:
#     bash verify/run_verify.sh
set -euo pipefail
cd "$(dirname "$0")"
VERIFY_DIR="$(pwd)"
PROJECT_DIR="$(dirname "${VERIFY_DIR}")"
cd "${PROJECT_DIR}"

echo "[1/4] Building operator (bash build.sh)"
bash build.sh

RUN_PKG="$(find build_out -maxdepth 1 -name 'custom_opp_*.run' | head -n 1 || true)"
if [ -z "${RUN_PKG}" ]; then
    echo "FAILED: no build_out/custom_opp_*.run package was produced" >&2
    exit 1
fi
echo "[2/4] Deploying operator package"
"${RUN_PKG}" --install-path="${HOME}/"

# Cloud Lab (910B family, CANN 9.0.0) quirk: the NPU reports socVersion
# "ascend910_93" while the op is compiled/installed under "ascend910b", so
# NNOP cannot find kernel/config/ascend910_93/binary_info_config.json and the
# first aclnn call fails with 161001. The two .o sets are interchangeable
# (same DAV_2201 arch), so mirror the installed dirs under the device soc
# name. Done on every run because build.sh + reinstall wipes the copy.
KERNEL_ROOT="${HOME}/vendors/customize/op_impl/ai_core/tbe/kernel"
if [ -d "${KERNEL_ROOT}/ascend910b" ] && [ ! -d "${KERNEL_ROOT}/ascend910_93" ]; then
    cp -r "${KERNEL_ROOT}/ascend910b" "${KERNEL_ROOT}/ascend910_93"
    echo "      soc alias: kernel/ascend910b -> kernel/ascend910_93"
fi
if [ -d "${KERNEL_ROOT}/config/ascend910b" ] && [ ! -d "${KERNEL_ROOT}/config/ascend910_93" ]; then
    cp -r "${KERNEL_ROOT}/config/ascend910b" "${KERNEL_ROOT}/config/ascend910_93"
    echo "      soc alias: kernel/config/ascend910b -> kernel/config/ascend910_93"
fi

echo "[3/4] Compiling the aclnn single-op runner"
g++ -I"${VERIFY_DIR}" -I"${ASCEND_TOOLKIT_HOME}/include" -I"${HOME}/vendors/customize/op_api/include" \
    -L"${ASCEND_TOOLKIT_HOME}/lib64" -L"${HOME}/vendors/customize/op_api/lib" \
    "${VERIFY_DIR}/aclnn_asc_try.cpp" -lcust_opapi -lnnopbase -lacl_rt -o "${VERIFY_DIR}/execute_op"
set +u
source "${HOME}/vendors/customize/bin/set_env.bash"
set -u

echo "[4/4] Running the op and comparing output.bin with golden.bin"
"${VERIFY_DIR}/execute_op" "${VERIFY_DIR}"
python3 "${VERIFY_DIR}/verify_result.py"
